  KEY `m_logsstanlog_rea_ix` (`realuserid`),
  KEY `m_logsstanlog_rel_ix` (`relateduserid`)
) ENGINE=InnoDB AUTO_INCREMENT=2297 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=COMPRESSED COMMENT='Standard log table';
