INSERT INTO `m_page` VALUES (1,2,'Filter test: Page render validations','<p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711022886486_1478\">MathType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«msqrt»«msqrt»«msqrt»«msqrt»«msqrt»«mi»x«/mi»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/math»</p><p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711022886486_1478\">ChemType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨ class=¨wrs_chemistry¨»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«mi mathvariant=¨normal¨»x«/mi»«/munder»«/munder»«/munder»«/munder»«/munder»«/math»</p><p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711022886486_1478\">Hand formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«mfrac»«mrow»«mn»1«/mn»«mo»+«/mo»«mn»2«/mn»«/mrow»«mn»3«/mn»«/mfrac»«/math»</p><p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711022886486_1478\">Styled formula:&nbsp;«math style=¨font-family:Verdana¨ xmlns=¨http://www.w3.org/1998/Math/MathML¨»«mstyle mathsize=¨24px¨»«msqrt mathcolor=¨#7F007F¨»«msqrt»«msqrt»«msqrt»«msqrt»«msqrt»«mi»y«/mi»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/mstyle»«/math»</p>',1,'<p dir=\"ltr\" style=\"text-align: left;\"></p><p dir=\"ltr\" id=\"yui_3_17_2_1_1711023169939_1545\">MathType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«msqrt»«msqrt»«msqrt»«msqrt»«msqrt»«mi»x«/mi»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/math»</p><p dir=\"ltr\">ChemType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨ class=¨wrs_chemistry¨»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«munder»«mo»§#8644;«/mo»«mi mathvariant=¨normal¨»x«/mi»«/munder»«/munder»«/munder»«/munder»«/munder»«/math»</p><p dir=\"ltr\">Hand formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«mfrac»«mrow»«mn»1«/mn»«mo»+«/mo»«mn»2«/mn»«/mrow»«mn»2«/mn»«/mfrac»«/math»<br></p><p dir=\"ltr\" id=\"yui_3_17_2_1_1711023169939_1592\">Styled formula:&nbsp;«math style=¨font-family:Tahoma¨ xmlns=¨http://www.w3.org/1998/Math/MathML¨»«mstyle mathsize=¨26px¨»«msqrt mathcolor=¨#7F007F¨»«msqrt»«msqrt»«msqrt»«msqrt»«mi»x«/mi»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/mstyle»«/math»</p><br><p></p>',1,0,NULL,5,'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}',3,1711023907),(2,2,'Filter test: Page render validations - LaTeX','<p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711023929890_1446\">$$\\sqrt{x+2}$$<br></p><p dir=\"ltr\" style=\"text-align: left;\"><br></p>',1,'<p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711023929890_1397\"></p><p dir=\"ltr\" id=\"yui_3_17_2_1_1711023929890_1446\">$$\\sqrt{x+2}$$<br></p><p dir=\"ltr\"><br></p><p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711023929890_1397\"><br></p>',1,0,NULL,5,'a:2:{s:10:\"printintro\";s:1:\"0\";s:17:\"printlastmodified\";s:1:\"1\";}',2,1711024006),(3,2,'Filter test: Page render validations - Wiris formulas + LaTeX','<p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711024024290_1424\">MathType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«mroot»«mroot»«mroot»«mroot»«mi»x«/mi»«mrow/»«/mroot»«mrow/»«/mroot»«mrow/»«/mroot»«mrow/»«/mroot»«/math»<br></p><p dir=\"ltr\" style=\"text-align: left;\" id=\"yui_3_17_2_1_1711024024290_1424\">LaTeX formula:&nbsp;<span style=\"font-size: 0.9375rem;\">$$\\sqrt{x+2}$$</span></p><p dir=\"ltr\"><br></p><p></p>',1,'<p dir=\"ltr\" style=\"text-align: left;\"></p><p dir=\"ltr\" id=\"yui_3_17_2_1_1711024024290_1424\">MathType formula:&nbsp;«math xmlns=¨http://www.w3.org/1998/Math/MathML¨»«msqrt»«msqrt»«msqrt»«msqrt»«msqrt»«mi»x«/mi»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/msqrt»«/math»<br></p><p dir=\"ltr\" id=\"yui_3_17_2_1_1711024024290_1424\">LaTeX formula:&nbsp;$$\\sqrt{x+2}$$</p><p dir=\"ltr\"><br></p><br><p></p>',1,0,NULL,5,'a:2:{s