  `rightanswer` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `responsesummary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `timemodified` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `m_quesatte_queslo_uix` (`questionusageid`,`slot`),
  KEY `m_quesatte_beh_ix` (`behaviour`),
  KEY `m_quesatte_que_ix` (`questionid`),
