INSERT INTO `m_question_attempts` VALUES (1,1,1,'manualgraded',169,1413,1.0000000,0.0000000,1.0000000,0,'Tell how many real roots has the following equation: [# a space x squared space plus space # b space x space plus space # c space thin space equals thin space 0]\n\nExplain why:\n\nTO BE DELETED\n',NULL,'43\n',1736238892),(2,1,2,'deferredfeedback',172,1,1.0000000,0.0000000,1.0000000,0,'Choose the correct solution of each integral\n {[integral left parenthesis sin left parenthesis x right parenthesis space plus space cos left parenthesis x right parenthesis right parenthesis squared d x]\n\n; [integral fraction numerator sin left parenthesis x right parenthesis over denominator 1 space plus space cos squared left parenthesis x right parenthesis end fraction d x]\n\n; [integral fraction numerator 1 over denominator 1 plus x squared end fraction d x]\n; [integral sin left parenthesis x right parenthesis d x]\n\n; [integral fraction numerator 2 over denominator 2 x plus 5 end fraction d x]\n\n} -> {-arctan(cos(x)) + C; ln(2x+5) + C; x - cos(2x)/2 + C; -cos(x) + C; arctan(x) + C}','[integral left parenthesis sin left parenthesis x right parenthesis space plus space cos left parenthesis x right parenthesis right parenthesis squared d x]\n\n -> x - cos(2x)/2 + C; [integral fraction numerator sin left parenthesis x right parenthesis over denominator 1 space plus space cos squared left parenthesis x right parenthesis end fraction d x]\n\n -> -arctan(cos(x)) + C; [integral fraction numerator 1 over denominator 1 plus x squared end fraction d x]\n -> arctan(x) + C; [integral sin left parenthesis x right parenthesis d x]\n\n -> -cos(x) + C; [integral fraction numerator 2 over denominator 2 x plus 5 end fraction d x]\n\n -> ln(2x+5) + C','[integral left parenthesis sin left parenthesis x right parenthesis space plus space cos left parenthesis x right parenthesis right parenthesis squared d x]\n\n -> x - cos(2x)/2 + C; [integral fraction numerator sin left parenthesis x right 